import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.io.FileNotFoundException;
import java.util.Scanner;
import java.util.ArrayList;

class TrustGenTest {

    private Terminal term;
    private Terminal term2;
    private TicketPassenger t1P;
    private TicketPassenger t1P2;
    private TicketPassenger t4P;
    private TicketBike t2B;
    private TicketBike t2B2;
    private TicketCar t3C;
    private TicketCar t3C2;
    private Terminal terminal;

    @BeforeEach
    void init() {
        String rawFile = """
            ^CAR TICKET
            DEPARTURE: Texel, 23-10-2024, 13:15
            ARRIVAL: Vlieland, 23-10-2024, 13:45
            PRICE: 70 euros
            LENGTH: <5meters
            PASSENGER: Swiatek, Iga
            PASSENGER: Zheng, Qinwen
            ^PASSENGER TICKET
            DEPARTURE: Texel, 23-10-2024, 15:15
            ARRIVAL: Terschelling, 23-10-2024, 15:45
            PRICE: 10 euros
            NAME: Verstappen, Max
            ^PASSENGER TICKET
            DEPARTURE: Texel, 24-10-2024, 15:15
            ARRIVAL: Terschelling, 24-10-2024, 15:45
            PRICE: 10 euros
            NAME: Pulling, Abbi
            ^CAR TICKET
            DEPARTURE: Terschelling, 25-10-2024, 13:00
            ARRIVAL: Vlieland, 25-10-2024, 14:00
            PRICE: 130 euros
            LENGTH: >=5meters
            PASSENGER: Sinner, Jannik
            PASSENGER: Alcaraz, Carlos
            PASSENGER: Djokovic, Novak
            ^BIKE TICKET
            DEPARTURE: Terschelling, 25-10-2024, 13:00
            ARRIVAL: Vlieland, 25-10-2024, 14:00
            PRICE: 25 euros
            PASSENGER: Vos, Marianne
            """;
        String outputFile = "All Tickets:\n" +
                "A CAR TICKET for passenger Iga Swiatek (driver) for the route Texel -> Vlieland on 23-10-2024.\n" +
                "Departure is scheduled for 13:15. Arrival is scheduled for 23-10-2024.\n" +
                "Additional passengers are: [Qinwen Zheng].\n" +
                "A PASSENGER TICKET for passenger Max Verstappen for the route Texel -> Terschelling on 23-10-2024.\n" +
                "Departure is scheduled for 15:15. Arrival is scheduled for 23-10-2024.\n" +
                "A PASSENGER TICKET for passenger Abbi Pulling for the route Texel -> Terschelling on 24-10-2024.\n" +
                "Departure is scheduled for 15:15. Arrival is scheduled for 24-10-2024.\n" +
                "A CAR TICKET for passenger Jannik Sinner (driver) for the route Terschelling -> Vlieland on 25-10-2024.\n" +
                "Departure is scheduled for 13:00. Arrival is scheduled for 25-10-2024.\n" +
                "Additional passengers are: [Carlos Alcaraz, Novak Djokovic].\n" +
                "A BIKE TICKET for passenger Marianne Vos for the route Terschelling -> Vlieland on 25-10-2024.\n" +
                "Departure is scheduled for 13:00. Arrival is scheduled for 25-10-2024.\n";
        term = ParseMaster.parseFile(new Scanner(rawFile));
        term2 = ParseMaster.parseFile(new Scanner(rawFile));
    }

    @BeforeEach
    void setup() {
        t1P = new TicketPassenger(new InfoTravel("Athens", "23-10-2024", "10:15"),
                new InfoTravel("Athens", "23-10-2024", "10:15"), 50, new HumanName("Ross", "Bob"));
        t1P2 = new TicketPassenger(new InfoTravel("Athens", "23-10-2024", "10:15"),
                new InfoTravel("Athens", "23-10-2024", "10:15"), 50, new HumanName("Ross", "Bob"));
        t4P = new TicketPassenger(new InfoTravel("Athens", "10-10-2024", "10:15"),
                new InfoTravel("Athens", "10-10-2024", "10:15"), 50, new HumanName("Ross", "Bob"));
        t2B = new TicketBike(new InfoTravel("Athens", "23-10-2024", "10:15"),
                new InfoTravel("Athens", "23-10-2024", "10:15"), 50, new HumanName("Ross", "Bob"));
        t2B2 = new TicketBike(new InfoTravel("Athens", "23-10-2024", "10:15"),
                new InfoTravel("Athens", "23-10-2024", "10:15"), 50, new HumanName("Ross", "Bob"));
        ArrayList<HumanName> passengers = new ArrayList<>();
        passengers.add(new HumanName("Verstapen", "Max"));
        passengers.add(new HumanName("Product", "Dot"));
        t3C = new TicketCar(new InfoTravel("Athens", "23-10-2024", "10:15"),
                new InfoTravel("Athens", "23-10-2024", "10:15"), 50, ">=4",
                new HumanName("Bakhodirjonov", "Umabrek"), passengers);
        t3C2 = new TicketCar(new InfoTravel("Athens", "23-10-2024", "10:15"),
                new InfoTravel("Athens", "23-10-2024", "10:15"), 50, ">=4",
                new HumanName("Bakhodirjonov", "Umabrek"), passengers);

        ArrayList<Ticket> ticketList = new ArrayList<>();
        ticketList.add(t1P);
        ticketList.add(t2B);
        ticketList.add(t3C);
        ticketList.add(t4P);
        terminal = new Terminal(ticketList);
    }

    @Test
    void trust_Option3RunsInSeparateThread() throws FileNotFoundException {
        String scriptedInput = "resources/waddenislands.txt\n3\nTerschelling\nVlieland\n";
        System.setIn(new ByteArrayInputStream(scriptedInput.getBytes()));
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        System.setOut(new PrintStream(outContent));

        try {
            new Main().main();
        } catch (java.util.NoSuchElementException expected) {
            // input exhausted as intended; Scanner throws when script runs out
        } finally {
            System.setIn(System.in);
            System.setOut(originalOut);
        }

        String output = outContent.toString();
        org.junit.jupiter.api.Assertions.assertTrue(
                output.contains("All tickets in the database for the route Terschelling -> Vlieland combined are worth 155 euros."),
                "Expected turnover message for route Terschelling -> Vlieland");
    }

    @Test
    void trust_Option3TurnoverValueMatchesExpected() throws FileNotFoundException {
        String scriptedInput = "resources/waddenislands.txt\n3\nTerschelling\nVlieland\n";
        System.setIn(new ByteArrayInputStream(scriptedInput.getBytes()));
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        System.setOut(new PrintStream(outContent));

        try {
            new Main().main();
        } catch (java.util.NoSuchElementException expected) {
            // input exhausted as intended; Scanner throws when script runs out
        } finally {
            System.setIn(System.in);
            System.setOut(originalOut);
        }

        String output = outContent.toString();
        org.junit.jupiter.api.Assertions.assertTrue(
                output.contains("155 euros"),
                "Expected combined ticket value of 155 euros for route Terschelling -> Vlieland");
    }
}

